static struct TreeNode *build(int *nums, int lo, int hi) {
  if (lo > hi) return NULL;
  int mid = lo + (hi - lo + 1) / 2;
  struct TreeNode *root = (struct TreeNode *)malloc(sizeof(struct TreeNode));
  root->val = nums[mid];
  root->left = build(nums, lo, mid - 1);
  root->right = build(nums, mid + 1, hi);
  return root;
}

struct TreeNode *sortedListToBST(struct ListNode *head) {
  int nums[20000];
  int n = 0;
  while (head != NULL) {
    nums[n++] = head->val;
    head = head->next;
  }
  return build(nums, 0, n - 1);
}

class Solution {
  TreeNode *build(vector<int> &nums, int lo, int hi) {
    if (lo > hi) return nullptr;
    int mid = lo + (hi - lo + 1) / 2;
    TreeNode *root = new TreeNode(nums[mid]);
    root->left = build(nums, lo, mid - 1);
    root->right = build(nums, mid + 1, hi);
    return root;
  }

public:
  TreeNode *sortedListToBST(ListNode *head) {
    vector<int> nums;
    while (head) {
      nums.push_back(head->val);
      head = head->next;
    }
    return build(nums, 0, (int)nums.size() - 1);
  }
};

func sortedListToBST(head *ListNode) *TreeNode {
	var nums []int
	for head != nil {
		nums = append(nums, head.Val)
		head = head.Next
	}
	var build func(lo, hi int) *TreeNode
	build = func(lo, hi int) *TreeNode {
		if lo > hi {
			return nil
		}
		mid := lo + (hi-lo+1)/2
		root := &TreeNode{Val: nums[mid]}
		root.Left = build(lo, mid-1)
		root.Right = build(mid+1, hi)
		return root
	}
	return build(0, len(nums)-1)
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private TreeNode build(List<Integer> nums, int lo, int hi) {
    if (lo > hi) return null;
    int mid = lo + (hi - lo + 1) / 2;
    TreeNode root = new TreeNode(nums.get(mid));
    root.left = build(nums, lo, mid - 1);
    root.right = build(nums, mid + 1, hi);
    return root;
  }

  public TreeNode sortedListToBST(ListNode head) {
    List<Integer> nums = new ArrayList<>();
    while (head != null) {
      nums.add(head.val);
      head = head.next;
    }
    return build(nums, 0, nums.size() - 1);
  }
}

class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        nums = []
        while head:
            nums.append(head.val)
            head = head.next

        def build(lo, hi):
            if lo > hi:
                return None
            mid = lo + (hi - lo + 1) // 2
            root = TreeNode(nums[mid])
            root.left = build(lo, mid - 1)
            root.right = build(mid + 1, hi)
            return root

        return build(0, len(nums) - 1)

impl Solution {
  pub fn sorted_list_to_bst(head: Option<Box<ListNode>>) -> Option<Box<TreeNode>> {
    let mut nums = vec![];
    let mut cur = head;
    while let Some(node) = cur {
      nums.push(node.val);
      cur = node.next;
    }
    Self::build(&nums)
  }

  fn build(nums: &[i32]) -> Option<Box<TreeNode>> {
    if nums.is_empty() {
      return None;
    }
    let mid = nums.len() / 2;
    let mut root = Box::new(TreeNode::new(nums[mid]));
    root.left = Self::build(&nums[..mid]);
    root.right = Self::build(&nums[mid + 1..]);
    Some(root)
  }
}

const sortedListToBST = (head: ListNode | null): TreeNode | null => {
  const nums: number[] = [];
  while (head) {
    nums.push(head.val);
    head = head.next;
  }
  const build = (lo: number, hi: number): TreeNode | null => {
    if (lo > hi) return null;
    const mid = lo + Math.floor((hi - lo + 1) / 2);
    const root = new TreeNode(nums[mid]);
    root.left = build(lo, mid - 1);
    root.right = build(mid + 1, hi);
    return root;
  };
  return build(0, nums.length - 1);
};
